exports.PASSWORD_MIN = 12;
/** Kebijakan kata sandi (dok. 11 K-02): panjang, huruf + angka, tidak memuat email. */
function passwordProblems(pw, email) {
    const out = [];
    if (pw.length < exports.PASSWORD_MIN)
        out.push(`Minimal ${exports.PASSWORD_MIN} karakter.`);
    if (pw.length > 200)
        out.push('Maksimal 200 karakter.');
    if (!/[A-Za-z]/.test(pw) || !/\d/.test(pw))
        out.push('Harus memuat huruf dan angka.');
    const local = email?.split('@')[0]?.toLowerCase();
    if (local && local.length >= 3 && pw.toLowerCase().includes(local))
        out.push('Tidak boleh memuat nama pengguna/email.');
    if (/^(.)\1+$/.test(pw) || /^(password|katasandi|rahasia)/i.test(pw))
        out.push('Terlalu mudah ditebak.');
    return out;
}
